create policy "Public reads portfolio images" on storage.objects for select using (bucket_id = 'portfolio');
create policy "Admins upload portfolio images" on storage.objects for insert to authenticated with check (bucket_id = 'portfolio' and public.has_role(auth.uid(), 'admin'));
create policy "Admins update portfolio images" on storage.objects for update to authenticated using (bucket_id = 'portfolio' and public.has_role(auth.uid(), 'admin'));
create policy "Admins delete portfolio images" on storage.objects for delete to authenticated using (bucket_id = 'portfolio' and public.has_role(auth.uid(), 'admin'));